from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    interior = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1) if grid[r][c] != 0]
    fill = Counter(interior).most_common(1)[0][0] if interior else grid[r0][c0]
    out = [row[:] for row in grid]
    for r in range(max(0, r0 - 2), min(h, r1 + 3)):
        for c in range(max(0, c0 - 2), min(w, c1 + 3)):
            if grid[r][c] == 0:
                out[r][c] = fill
    return out
